//! FES2004 ocean-tide geopotential coefficients (IERS Conventions 2010, Eq. 6.15) --
//! machine-generated by `derivations/ocean_tide_fes2004.py` from `fes2004_Cnm-Snm.dat`.
//! Verbatim file values; the 10^-11 unit is [`SCALE`], applied at use (as Orekit does).
//! Regenerate, never hand-edit.

// Verbatim FES2004 coefficients: many share the same few significant digits.
#![allow(
    clippy::unreadable_literal,
    clippy::excessive_precision,
    clippy::approx_constant
)]

/// FES2004 coefficient scale: file values are in units of 10^-11 (Orekit `FESCnmSnmReader`).
pub const SCALE: f64 = 1.0e-11;

/// One Doodson tide wave: its Doodson number and the fully-normalized prograde/retrograde
/// coefficients `(n, m, C+, S+, C-, S-)` (verbatim, in units of [`SCALE`]) for degree n >= 2.
pub struct OceanTideWave {
    /// Doodson number, e.g. 255555 for M2 (the six-digit tidal argument code).
    pub doodson: u32,
    /// `(degree n, order m, C+, S+, C-, S-)` rows; absent (n, m) contribute nothing.
    pub coeffs: &'static [(u8, u8, f64, f64, f64, f64)],
}

